<?php
require_once __DIR__ . '/../../admin/implements/conexion.php';
require_once __DIR__ . '/funciones.php';
exigirAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){validarPost();$uid=(int)($_POST['id_usuario']??0);$lid=(int)($_POST['id_libro']??0);$fp=trim($_POST['fecha_prestamo']??'');$fd=trim($_POST['fecha_devolucion']??'');if(!$uid||!$lid||!fechaValida($fp)||!fechaValida($fd)||$fd<$fp){mensaje('error','Selecciona usuario, libro y fechas válidas.');}else{try{$pdo->beginTransaction();$usuario=$pdo->prepare("SELECT id_usuario FROM usuarios WHERE id_usuario=? AND rol='Usuario'");$usuario->execute([$uid]);if(!$usuario->fetch())throw new RuntimeException('El usuario lector no existe.');$libro=$pdo->prepare('SELECT estado FROM libros WHERE id_libro=? FOR UPDATE');$libro->execute([$lid]);$fila=$libro->fetch();if(!$fila||$fila['estado']!=='Disponible')throw new RuntimeException('El libro ya no está disponible.');$pdo->prepare("INSERT INTO prestamos(id_usuario,id_libro,fecha_prestamo,fecha_devolucion,estado_prestamo) VALUES(?,?,?,?,'Activo')")->execute([$uid,$lid,$fp,$fd]);$pdo->prepare("UPDATE libros SET estado='Prestado' WHERE id_libro=?")->execute([$lid]);$pdo->commit();mensaje('ok','Préstamo registrado.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();mensaje('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo registrar el préstamo.');}}header('Location: listado.php');exit;}
$usuarios=$pdo->query("SELECT id_usuario,nombre FROM usuarios WHERE rol='Usuario' ORDER BY nombre")->fetchAll();$libros=$pdo->query("SELECT id_libro,titulo FROM libros WHERE estado='Disponible' ORDER BY titulo")->fetchAll();$registros=obtenerPrestamosRecientes(100);iniciarPagina('Préstamos');barraNavegacion('prestamos-listado.php');
?>
<div class="encabezado-pagina"><div><span class="sobrelinea">CIRCULACIÓN</span><h1>Préstamos</h1><p>Asigna libros disponibles a los usuarios.</p></div></div><section class="panel mb-4"><h2>Nuevo préstamo</h2><form method="post" class="row g-3"><input type="hidden" name="token_csrf" value="<?= escapar(tokenCsrf()); ?>"><div class="col-md-3"><label class="form-label">Usuario</label><select class="form-select" name="id_usuario" required><option value="">Seleccionar</option><?php foreach($usuarios as $u): ?><option value="<?= (int)$u['id_usuario']; ?>"><?= escapar($u['nombre']); ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Libro disponible</label><select class="form-select" name="id_libro" required><option value="">Seleccionar</option><?php foreach($libros as $l): ?><option value="<?= (int)$l['id_libro']; ?>"><?= escapar($l['titulo']); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Fecha préstamo</label><input class="form-control" type="date" name="fecha_prestamo" value="<?= date('Y-m-d'); ?>" required></div><div class="col-md-2"><label class="form-label">Fecha devolución</label><input class="form-control" type="date" name="fecha_devolucion" value="<?= date('Y-m-d',strtotime('+14 days')); ?>" required></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Crear</button></div></form></section><section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Préstamo</th><th>Devolución</th><th>Estado</th></tr></thead><tbody><?php foreach($registros as $p): ?><tr><td><?= escapar($p['usuario']); ?></td><td><?= escapar($p['libro']); ?></td><td><?= escapar($p['fecha_prestamo']); ?></td><td><?= escapar($p['fecha_devolucion']); ?></td><td><?= escapar($p['estado_vista']); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php finPagina(); ?>
